<div class="section-heading"><div><h2>Saved views</h2><p class="muted">Keep a useful combination of filters and layout one click away.</p></div></div><?php if(!$views): ?><section class="card empty"><h3>Your workflow, your view.</h3><p>Save a board for a cycle, a high-priority list, or an assignee’s work.</p></section><?php else: ?><div class="website-grid"><?php foreach($views as $view): ?><article class="card"><span class="website-kicker"><?= e(WorkService::LAYOUTS[$view['layout']]) ?></span><h2><?= e($view['name']) ?></h2><div class="hero-actions"><a class="btn secondary" href="<?= $workPath ?>?view_id=<?= e($view['id']) ?>">Open view</a><form method="post" action="<?= $workPath ?>/view/<?= e($view['id']) ?>/remove" data-confirm="Remove this saved view? Work items will be kept."><?= csrf_field() ?><button class="quiet">Remove</button></form></div><details><summary>Edit view</summary><?php $viewEditing=$view;require __DIR__.'/view-form.php'; ?></details></article><?php endforeach; ?></div><?php endif; ?>
<section class="card"><h2>Create a saved view</h2><?php $viewEditing=null;require __DIR__.'/view-form.php'; ?></section>
